// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address depositor, uint256 amount) public {
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, type(uint128).max);

        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();

        vm.prank(depositor);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            vm.prank(depositor);
            bool ok2;
            try c.withdrawAll() {
                ok2 = true;
            } catch {
                ok2 = false;
            }

            assertTrue(ok2);
        }
    }
}
